(() => {
  const root = document.querySelector('#root');
  const toastEl = document.querySelector('#toast');
  const pathParts = location.pathname.split('/').filter(Boolean);
  const role = pathParts[0] === 'dm' ? 'dm' : pathParts[0] === 'player' ? 'player' : pathParts[0] === 'projector' ? 'projector' : 'home';
  const playerId = role === 'player' ? Math.max(1, Math.min(6, Number(pathParts[1]) || 1)) : 0;
  let state = null, activeTab = 'mesa', selectedToken = '', toastTimer = null, sheetPage='combat', dmSheetPlayerId=1, catalogKind='', catalogTargetKind='monster', audioUnlocked=false, audioSource='', mapSelectedToken='', sheetSaveTimer=null, campaignSaveTimer=null, sheetSaveBusy=false, sheetSaveQueued=false;
  const sharedAudio = new Audio(); sharedAudio.loop=true; sharedAudio.preload='none';
  const CLASS_INFO={"Bárbaro":12,"Bardo":8,"Clérigo":8,"Druida":8,"Guerreiro":10,"Monge":8,"Paladino":10,"Patrulheiro":10,"Ladino":8,"Feiticeiro":6,"Bruxo":8,"Mago":6};
  const SPECIES=['','Anão','Elfo','Halfling','Humano','Draconato','Gnomo','Meio-elfo','Meio-orc','Tiefling','Aasimar','Firbolg','Genasi','Golias','Goblin','Kenku','Orc','Tabaxi','Tritão','Personalizada'];
  const BACKGROUNDS=['','Acólito','Charlatão','Criminoso','Artista','Herói do Povo','Artesão da Guilda','Eremita','Nobre','Forasteiro','Sábio','Marinheiro','Soldado','Órfão','Personalizado'];
  const ALIGNMENTS=['','Leal e Bom','Neutro e Bom','Caótico e Bom','Leal e Neutro','Neutro','Caótico e Neutro','Leal e Mau','Neutro e Mau','Caótico e Mau','Sem alinhamento'];
  const SUBCLASSES={'Bárbaro':['Caminho do Berserker','Caminho do Guerreiro Totémico'],'Bardo':['Colégio do Conhecimento','Colégio da Bravura'],'Clérigo':['Domínio do Conhecimento','Domínio da Vida','Domínio da Luz','Domínio da Natureza','Domínio da Tempestade','Domínio da Trapaça','Domínio da Guerra'],'Druida':['Círculo da Terra','Círculo da Lua'],'Guerreiro':['Campeão','Mestre de Batalha','Cavaleiro Arcano'],'Monge':['Caminho dos Quatro Elementos','Caminho da Mão Aberta','Caminho da Sombra'],'Paladino':['Juramento dos Anciões','Juramento da Devoção','Juramento da Vingança'],'Patrulheiro':['Mestre das Feras','Caçador'],'Ladino':['Trapaceiro Arcano','Assassino','Ladrão'],'Feiticeiro':['Linhagem Dracónica','Magia Selvagem'],'Bruxo':['A Arquifada','O Corruptor','O Grande Antigo'],'Mago':['Abjuração','Conjuração','Adivinhação','Encantamento','Evocação','Ilusão','Necromancia','Transmutação']};
  const SKILLS=[['Acrobacia','dex'],['Adestrar animais','wis'],['Arcanismo','int'],['Atletismo','str'],['Atuação','cha'],['Enganação','cha'],['Furtividade','dex'],['História','int'],['Intimidação','cha'],['Intuição','wis'],['Investigação','int'],['Medicina','wis'],['Natureza','int'],['Perceção','wis'],['Persuasão','cha'],['Prestidigitação','dex'],['Religião','int'],['Sobrevivência','wis']];
  const ABILITIES=[['str','Força'],['dex','Destreza'],['con','Constituição'],['int','Inteligência'],['wis','Sabedoria'],['cha','Carisma']];
  const $ = (s, el=document) => el.querySelector(s);
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const initials = s => (String(s || '?').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('') || '?').toUpperCase();
  const pct = (hp,max) => Math.max(0,Math.min(100,100*(Number(hp)||0)/(Number(max)||1)));
  const activePlayer = () => state?.players?.find(p => p.id === playerId) || {id:playerId,name:`Player ${playerId}`,character:'',hp:10,maxHp:10,ac:10,level:1,stats:{},effects:[]};
  function toast(msg) { toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2800); }
  function syncAudio() {
    const url=state?.battle?.audioUrl||''; const shouldPlay=state?.campaign?.mode==='battle'&&url;
    if(url&&url!==audioSource){audioSource=url;sharedAudio.src=url;sharedAudio.load();}
    sharedAudio.volume=Math.max(0,Math.min(1,(Number(state?.battle?.volume)||70)/100));
    if(shouldPlay&&audioUnlocked)sharedAudio.play().catch(()=>{});else if(!shouldPlay)sharedAudio.pause();
  }
  function normalizeState(value) {
    const s=value&&typeof value==='object'?value:{};
    s.campaign={name:'Nova campanha',chapter:'Capítulo I',mode:'normal',round:1,activeTurn:0,...(s.campaign||{})};
    s.battle={audioUrl:'',audioName:'',volume:70,...(s.battle&&typeof s.battle==='object'?s.battle:{})};
    s.map={url:'',name:'',visible:false,grid:true,gridSize:48,tokens:{},annotations:[],...(s.map||{})};
    s.map.tokens ||= {}; s.map.annotations ||= [];
    s.players=Array.isArray(s.players)?s.players:[]; s.monsters=Array.isArray(s.monsters)?s.monsters:[]; s.bosses=Array.isArray(s.bosses)?s.bosses:[]; s.rolls=Array.isArray(s.rolls)?s.rolls:[]; s.log=Array.isArray(s.log)?s.log:[];s.campaigns=Array.isArray(s.campaigns)?s.campaigns:[];
    return s;
  }
  async function api(type, extra={}) {
    try { const res=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({role,playerId,type,...extra})}); const data=await res.json();if(!res.ok)throw new Error(data.error||'Falha no pedido.');return data; }
    catch(e){toast(e.message);throw e;}
  }
  async function load() { const res=await fetch(`/api/state?role=${role==='home'?'projector':role}&id=${playerId}`);if(!res.ok)throw new Error(`O servidor respondeu ${res.status}.`);state=normalizeState(await res.json());render(); }
  function header(title='') {
    const roleName=role==='dm'?'Sala do DM':role==='player'?`Player ${playerId}`:'Ecrã de jogadores';
    const modeLabel={normal:'◌ Normal',day:'☀ Dia',night:'☾ Noite',battle:'⚔ Batalha'}[state.campaign.mode]||'◌ Normal';
    return `<header class="topbar"><div class="brand"><div class="brand-mark">&</div><div><div class="brand-title">CRÓNICAS</div><div class="brand-sub">mesa de campanha local</div></div></div><div class="campaign-chip">${esc(state.campaign.name)} · ${esc(state.campaign.chapter||'Capítulo I')}</div><div class="top-actions"><span class="pill"><i class="dot"></i> ${role==='player'||role==='projector'?modeLabel:'Ligação local'}</span>${role==='dm'?`<button class="btn small ghost" data-action="export">Exportar</button><label class="btn small ghost" for="import-file">Importar</label><input id="import-file" class="file-hidden" type="file" accept=".json,application/json">`:''}<a class="btn small ghost" href="/">⌂ Início</a></div></header>`;
  }
  function navTabs(items, current) { return `<nav class="tabs">${items.map(([id,label,icon])=>`<button class="tab ${id===current?'active':''}" data-tab="${id}">${icon||''} ${label}</button>`).join('')}</nav>`; }
  function actorCard(e, kind='player', dm=false) {
    const name=e.character||e.name||'Sem nome', subtitle=kind==='player'?`${e.ancestry||'Aventureiro'} · ${e.className||'Classe por definir'} · Nível ${e.level||1}`:`CA ${e.ac||10} · ${kind==='boss'?'Boss':'Criatura'}`;
    const badge=kind==='boss'?'boss':kind==='monster'?'monster':'player';
    const effects=(e.effects||[]).map(x=>`<span class="effect">${esc(x)}</span>`).join('');
    return `<article class="actor ${e.visible===false?'actor-hidden':''}"><div class="actor-top"><div class="avatar">${esc(initials(name))}</div><div class="grow"><div class="actor-name">${esc(name)}</div><div class="actor-meta">${esc(subtitle)}</div></div>${kind==='player'?`<span class="mode">P${e.id}</span>`:''}</div><div class="hp-line"><i style="width:${pct(e.hp,e.maxHp)}%"></i></div><div class="hp-copy"><span>${Number(e.hp)||0} PV</span><span>máx. ${Number(e.maxHp)||0} · CA ${Number(e.ac)||10}</span></div>${effects?`<div class="effects">${effects}</div>`:''}${dm?`<div class="actor-actions"><button class="btn small" data-action="heal-prompt" data-kind="${badge}" data-id="${esc(e.id)}" data-name="${esc(name)}">Curar</button><button class="btn small danger" data-action="damage-prompt" data-kind="${badge}" data-id="${esc(e.id)}" data-name="${esc(name)}">Dano</button><button class="btn small" data-action="effect-prompt" data-kind="${badge}" data-id="${esc(e.id)}" data-name="${esc(name)}">Efeito</button>${kind==='player'?`<button class="btn small ${e.visible===false?'primary':'ghost'}" data-action="player-visibility" data-id="${e.id}">${e.visible===false?'Mostrar':'Ocultar'}</button><button class="btn small" data-action="select-sheet-player" data-id="${e.id}">Ficha</button>`:`<select class="die-select" data-entity-die data-kind="${badge}" data-id="${esc(e.id)}">${['d4','d6','d8','d10','d12','d20','d100'].map(d=>`<option ${String(e.die||'d20')===d?'selected':''}>${d}</option>`).join('')}</select><button class="btn small" data-action="roll-entity" data-kind="${badge}" data-id="${esc(e.id)}" data-name="${esc(name)}">Rolar dado</button><button class="btn small" data-action="visibility-entity" data-kind="${badge}" data-id="${esc(e.id)}">${e.visible===false?'Revelar':'Ocultar'}</button><button class="btn small danger" data-action="delete-entity" data-kind="${badge}" data-id="${esc(e.id)}">Remover</button>`}</div>`:''}</article>`;
  }
  function feed(items) { if(!items?.length)return '<div class="empty-state">Ainda não há registos. Os dados e acontecimentos da mesa aparecerão aqui.</div>'; return `<div class="feed">${items.map(x=>`<div class="feed-item"><span class="feed-time">${new Date(x.at).toLocaleTimeString('pt-PT',{hour:'2-digit',minute:'2-digit'})}</span><span class="feed-text">${esc(x.text||`${x.who} lançou d${x.sides}: ${x.total}`)}</span></div>`).join('')}</div>`; }
  function rollPanel() { return `<section class="panel"><div class="panel-head"><h2>Rolador de dados</h2><small>resultados partilhados com a mesa</small></div><form class="dice-row" id="roll-form"><div class="field"><label>TIPO DE DADO</label><select name="sides"><option>20</option><option>12</option><option>10</option><option>8</option><option>6</option><option>4</option><option>100</option></select></div><div class="field"><label>QUANTIDADE</label><input name="count" type="number" min="1" max="20" value="1"></div><div class="field"><label>MODIFICADOR</label><input name="bonus" type="number" value="0"></div><button class="btn primary">Rolar</button></form><div id="last-roll">${rollResult(state.rolls[0])}</div></section>`; }
  function rollResult(r) { return r?`<div class="roll-result"><div class="subtle">${esc(r.who)} · ${r.count}d${r.sides}${r.bonus?(r.bonus>0?'+':'')+r.bonus:''}</div><strong>${Number(r.total)}</strong><span class="subtle"> &nbsp; [${(r.dice||[]).join(' · ')}]</span></div>`:''; }
  function mapHtml(mode) {
    const isDm=mode==='dm', shown=isDm||state.map.visible;
    if(!state.map.url)return `<div class="map-frame empty">${isDm?'Carrega uma imagem do mapa para começar.':shown?'O DM ainda não carregou um mapa.':'O mapa está oculto pelo DM.'}</div>`;
    if(!shown)return `<div class="map-frame empty">O mapa está oculto pelo DM.</div>`;
    const actors=[...(state.players||[]).filter(x=>isDm||x.visible!==false).map(x=>({...x,_kind:'player',_id:x.id,_name:x.character||x.name,_image:x.sheet?.identity?.portraitUrl||x.image||''})),...state.monsters.filter(x=>isDm||x.visible!==false).map(x=>({...x,_kind:'monster',_id:x.id,_name:x.name,_image:x.image||''})),...state.bosses.filter(x=>isDm||x.visible!==false).map(x=>({...x,_kind:'boss',_id:x.id,_name:x.name,_image:x.image||''}))];
    const tokens=actors.map(e=>{const key=`${e._kind}:${e._id}`,pos=state.map.tokens?.[key]||{x:.2+(Math.abs(Number(e._id)||1)%5)*.1,y:.25+(Math.abs(Number(e._id)||1)%4)*.12};const size=Math.max(24,Math.min(128,Number(pos.size)||42));return `<div class="map-token ${e._kind}" data-token="${esc(key)}" data-name="${esc(e._name)}" style="left:${pos.x*100}%;top:${pos.y*100}%;--token-size:${size}px" title="${esc(e._name)}">${e._image?`<img src="${esc(e._image)}" alt="" draggable="false">`:esc(initials(e._name))}</div>`;}).join('');
    const notes=(state.map.annotationsVisible!==false||isDm?(state.map.annotations||[]):[]).filter(n=>n.text).map(n=>`<div class="map-token map-note" style="left:${n.x*100}%;top:${n.y*100}%;width:auto;height:auto;padding:7px 10px;border-radius:9px;transform:translate(-50%,-50%);color:${esc(n.color)}">${esc(n.text)}</div>`).join('');
    const lines=(state.map.annotations||[]).filter(n=>n.points?.length>1).map(n=>`<polyline points="${n.points.map(p=>`${p.x*1000},${p.y*1000}`).join(' ')}" fill="none" stroke="${esc(n.color||'#e3bd63')}" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>`).join('');
    return `<div class="map-frame" data-map="true"><img class="map-image" src="${esc(state.map.url)}" alt="${esc(state.map.name)}"><div class="map-grid" style="--grid-size:${Number(state.map.gridSize)||48}px;display:${state.map.grid?'block':'none'}"></div><svg class="map-draw-layer" data-draw-layer viewBox="0 0 1000 1000" preserveAspectRatio="none" style="pointer-events:${role==='dm'&&selectedToken==='__draw__'?'auto':'none'};cursor:crosshair">${lines}</svg><div class="map-overlay">${esc(state.map.name||'MAPA DE ENCONTRO')}</div>${tokens}${notes}</div>`;
  }
  const field=(path,label,value='',type='text',options=null)=>`<div class="field"><label>${esc(label)}</label>${options?`<select class="input" data-path="${path}">${options.map(o=>`<option ${String(o)===String(value)?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input class="input" data-path="${path}" type="${type}" value="${esc(value)}">`}</div>`;
  const textArea=(path,label,value='',rows=4)=>`<div class="field full"><label>${esc(label)}</label><textarea class="input" data-path="${path}" rows="${rows}">${esc(value)}</textarea></div>`;
  function proficiencyList(path,items,selected,abilities,prof) { return `<div class="proficiency-list">${items.map(([name,ability])=>{const value=Math.floor(((Number(abilities[ability])||10)-10)/2)+((selected||[]).includes(name)?prof:0);return `<label class="prof-row"><input type="checkbox" data-listpath="${path}" value="${esc(name)}" ${(selected||[]).includes(name)?'checked':''}><span class="prof-ability">${ability.toUpperCase()}</span><span class="prof-name">${esc(name)}</span><b>${value>=0?'+':''}${value}</b></label>`;}).join('')}</div>`; }
  function renderSheet(p, isDm=false) {
    const s=p.sheet||{}, identity=s.identity||{}, abilities=s.abilities||{}, hp=s.hp||{}, combat=s.combat||{}, currentTab=sheetPage;
    const abilityMod=key=>Math.floor(((Number(abilities[key])||10)-10)/2);
    const prof=Number(combat.proficiency)||2;
    const skillPath=key=>key.toLowerCase();
    const statFields=ABILITIES.map(([key,label])=>`<div class="ability-box"><span>${label}</span><input type="number" min="1" max="30" data-path="abilities.${key}" value="${Number(abilities[key])||10}"><b>${abilityMod(key)>=0?'+':''}${abilityMod(key)}</b></div>`).join('');
    const sheetTabs=[['combat','Combate'],['equipment','Equipamento'],['history','História'],['spells','Magias']];
    let detail='';
    if(currentTab==='combat') detail=`<div class="sheet-columns"><div class="stack"><section class="sheet-panel"><h3>Atributos</h3><div class="ability-grid">${statFields}</div></section><section class="sheet-panel"><h3>Testes de resistência</h3>${proficiencyList('saves',ABILITIES.map(([k,n])=>[n,k]),s.saves,abilities,prof)}</section><section class="sheet-panel"><h3>Perícias</h3>${proficiencyList('skills',SKILLS,s.skills,abilities,prof)}</section><section class="sheet-panel"><h3>Sentidos passivos</h3><div class="stats">${[['Perceção','Perceção','wis'],['Intuição','Intuição','wis'],['Investigação','Investigação','int']].map(([label,key,ability])=>`<div class="stat"><b>${10+abilityMod(ability)+((s.skills||[]).includes(key)?prof:0)}</b><span>${label}</span></div>`).join('')}</div></section></div><div class="stack"><section class="sheet-panel"><h3>Combate</h3><div class="form-grid">${field('combat.initiative','Iniciativa',combat.initiative||0,'number')}${field('ac','Classe de armadura',s.ac||10,'number')}${field('combat.proficiency','Bónus de proficiência',prof,'number')}${field('combat.speed','Deslocamento',combat.speed||'9 m')}${field('combat.inspiration','Inspiração heroica',combat.inspiration||0,'number')}${field('combat.hitDice','Dados de vida',combat.hitDice||'')}${field('combat.spellcastingAbility','Atributo de magia',combat.spellcastingAbility||'','text',['','Força','Destreza','Constituição','Inteligência','Sabedoria','Carisma'])}${field('combat.spellSaveDc','CD de salvaguarda',combat.spellSaveDc||'','number')}${field('combat.spellAttackBonus','Bónus de ataque mágico',combat.spellAttackBonus||'','number')}</div></section><section class="sheet-panel"><h3>Defesas e condições</h3><div class="form-grid">${textArea('defenses','Resistências, imunidades e vulnerabilidades',s.defenses||'',3)}${textArea('conditions','Condições ativas',s.conditions||'',2)}${textArea('proficiencies','Proficiências e treino',s.proficiencies||'',3)}</div></section><section class="sheet-panel"><h3>Ações</h3>${textArea('actions','Ações, características e notas de combate',s.actions||'',4)}</section></div><div class="stack"><section class="sheet-panel"><h3>Pontos de vida</h3><div class="form-grid">${field('hp.max','Máximo',hp.max||p.maxHp||10,'number')}${field('hp.current','Atuais',hp.current??p.hp??10,'number')}${field('hp.temp','Temporários',hp.temp||0,'number')}</div><div class="row" style="margin-top:8px">${isDm?`<button class="btn small" type="button" data-action="heal-sheet" data-id="${p.id}">Curar</button><button class="btn small danger" type="button" data-action="damage-sheet" data-id="${p.id}">Dano</button>`:''}<button class="btn small" type="button" data-action="calculate-hp">Calcular PV</button></div><div class="hp-line"><i style="width:${pct(hp.current??p.hp,hp.max??p.maxHp)}%"></i></div></section><section class="sheet-panel"><h3>Salvaguardas contra a morte</h3>${['successes','failures'].map(k=>`<div class="death-row"><span>${k==='successes'?'Sucessos':'Falhas'}</span>${[0,1,2].map(i=>`<input type="checkbox" data-death="${k}.${i}" ${s.deathSaves?.[k]?.[i]?'checked':''}>`).join('')}</div>`).join('')}</section><section class="sheet-panel"><h3>Ataques e truques</h3><div class="table-scroll"><table class="table"><thead><tr><th>Nome</th><th>Ataque</th><th>Dano</th><th>Notas</th></tr></thead><tbody>${Array.from({length:6},(_,i)=>`<tr>${['name','hit','damage','notes'].map(key=>`<td><input class="sheet-cell" data-path="attacks.${i}.${key}" value="${esc(s.attacks?.[i]?.[key]||'')}"></td>`).join('')}</tr>`).join('')}</tbody></table></div></section></div></div>`;
    if(currentTab==='equipment') { const inv=s.inventory||[];detail=`<div class="sheet-columns"><section class="sheet-panel wide"><div class="panel-head"><h3>Inventário</h3><button class="btn small" type="button" data-action="api-catalog" data-kind="equipment">＋ Escolher arma ou objeto da API</button></div><div class="table-scroll"><table class="table inventory-table"><thead><tr><th>Objeto</th><th>Qtd.</th><th>Peso</th><th>Notas</th></tr></thead><tbody>${Array.from({length:12},(_,i)=>`<tr>${['name','quantity','weight','notes'].map(key=>`<td><input class="sheet-cell" data-path="inventory.${i}.${key}" value="${esc(inv[i]?.[key]||'')}"></td>`).join('')}</tr>`).join('')}</tbody></table></div>${textArea('extras','Itens sintonizados e recursos',s.history?.extras||'',3)}</section><section class="sheet-panel"><h3>Moedas e carga</h3><div class="form-grid">${['cp','sp','ep','gp','pp'].map((k,i)=>field(`currency.${k}`,['PC','PP','PE','PO','PL'][i],s.currency?.[k]??'0','number')).join('')}${field('carrying.weight','Peso transportado',s.carrying?.weight||'')}${field('carrying.encumbered','Carga máxima',s.carrying?.encumbered||'')}${field('carrying.lift','Empurrar / arrastar / levantar',s.carrying?.lift||'')}</div>${textArea('history.extras','Notas de equipamento',s.history?.extras||'',4)}</section><section class="sheet-panel"><h3>Características e traços</h3>${textArea('features','Características raciais, de classe e talentos',s.features||'',10)}</section></div>`; }
    if(currentTab==='history') { const a=s.appearance||{},h=s.history||{};detail=`<div class="sheet-columns"><section class="sheet-panel"><h3>Aspeto e identidade</h3><div class="form-grid">${[['gender','Género'],['age','Idade'],['size','Tamanho'],['height','Altura'],['weight','Peso'],['eyes','Olhos'],['hair','Cabelo'],['skin','Pele'],['faith','Fé'],['allies','Aliados e organizações']].map(([k,label])=>field(`appearance.${k}`,label,a[k]||'')).join('')}${textArea('appearance.description','Descrição física',a.description||'',5)}</div></section><section class="sheet-panel"><h3>História e personalidade</h3><div class="form-grid">${textArea('history.story','História da personagem',h.story||'',9)}${textArea('history.personality','Traços de personalidade',h.personality||'',4)}${textArea('history.ideals','Ideais',h.ideals||'',4)}${textArea('history.bonds','Ligações',h.bonds||'',4)}${textArea('history.flaws','Defeitos',h.flaws||'',4)}${textArea('history.notes','Notas',h.notes||'',8)}</div></section></div>`; }
    if(currentTab==='spells') { const spells=s.spells||[];detail=`<div class="sheet-columns"><section class="sheet-panel wide"><div class="panel-head"><h3>Livro de magias</h3><button class="btn small" type="button" data-action="api-catalog" data-kind="spells">＋ Escolher magia da API</button></div><div class="table-scroll"><table class="table spells-table"><thead><tr><th>Prep.</th><th>Nome</th><th>Fonte</th><th>Save / ATK</th><th>Tempo</th><th>Alcance</th><th>Comp.</th><th>Duração</th><th>Nível / Ref.</th><th>Notas</th></tr></thead><tbody>${Array.from({length:17},(_,i)=>{const sp=spells[i]||{};return `<tr><td><input type="checkbox" data-path="spells.${i}.prepared" ${sp.prepared?'checked':''}></td>${['name','source','save','time','range','components','duration','level','notes'].map(key=>`<td><input class="sheet-cell" data-path="spells.${i}.${key}" value="${esc(sp[key]||'')}"></td>`).join('')}</tr>`;}).join('')}</tbody></table></div>${textArea('spellcasting.notes','Notas de conjuração',s.spellcasting?.notes||'',4)}</section><section class="sheet-panel"><h3>Conjuração</h3><div class="form-grid">${field('spellcasting.ability','Atributo de conjuração',s.spellcasting?.ability||'','text',['','Inteligência','Sabedoria','Carisma'])}${field('spellcasting.saveDc','CD de salvaguarda',s.spellcasting?.saveDc||'','number')}${field('spellcasting.attackBonus','Bónus de ataque mágico',s.spellcasting?.attackBonus||'','number')}</div><h3 class="section-title" style="margin-top:16px">Espaços de magia por nível</h3><div class="slot-grid">${Array.from({length:9},(_,i)=>field(`spellcasting.slots.${i+1}`,`Nível ${i+1}`,s.spellcasting?.slots?.[i+1]||'','number')).join('')}</div></section></div>`; }
    const classOptions=['','Bárbaro','Bardo','Clérigo','Druida','Guerreiro','Monge','Paladino','Patrulheiro','Ladino','Feiticeiro','Bruxo','Mago'];
    const identityFields=`${field('identity.name','Nome da personagem',identity.name||'')}${field('identity.className','Classe',identity.className||'','text',classOptions)}${field('identity.level','Nível',identity.level||1,'number')}${field('identity.subclass','Subclasse / arquétipo',identity.subclass||'','text',['',...(SUBCLASSES[identity.className]||[])])}${field('identity.ancestry','Espécie / raça',identity.ancestry||'','text',SPECIES)}${field('identity.background','Antecedente',identity.background||'','text',BACKGROUNDS)}${field('identity.alignment','Alinhamento',identity.alignment||'','text',ALIGNMENTS)}${field('identity.playerName','Nome do jogador',identity.playerName||p.name||'')}${field('identity.xp','Pontos de experiência',identity.xp||'','number')}`;
    return `<section class="sheet-shell"><div class="sheet-identity"><div class="avatar sheet-portrait">${identity.portraitUrl?`<img src="${esc(identity.portraitUrl)}" alt="Retrato de ${esc(identity.name||p.name)}">`:esc(initials(identity.name||p.character||p.name))}</div><div class="identity-fields">${identityFields}</div></div><div class="sheet-summary">${ABILITIES.map(([k,label])=>`<div class="summary-stat"><span>${label}</span><b>${abilityMod(k)>=0?'+':''}${abilityMod(k)}</b><small>${Number(abilities[k])||10}</small></div>`).join('')}<div class="summary-stat prof"><span>Proficiência</span><b>+${prof}</b><small>BÓNUS</small></div><div class="summary-stat hp"><span>Pontos de vida</span><b>${Number(hp.current??p.hp)||0}/${Number(hp.max??p.maxHp)||10}</b><small>PV</small></div></div><div class="sheet-toolbar"><div><div class="eyebrow">Ficha nativa · 5.ª edição</div><div class="subtle">${esc(identity.name||p.name)} · ${esc(identity.className||'Classe por definir')} · Nível ${identity.level||1}</div></div><div class="row"><label class="btn small" for="portrait-file">Retrato</label><input id="portrait-file" class="file-hidden" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><button class="btn small" type="button" data-action="api-catalog" data-kind="spells">Magias da API</button><button class="btn small" type="button" data-action="api-catalog" data-kind="equipment">Armas / objetos da API</button></div></div><nav class="sheet-nav">${sheetTabs.map(([key,title])=>`<button class="tab ${currentTab===key?'active':''}" type="button" data-sheet-tab="${key}">${title}</button>`).join('')}</nav><form id="sheet-form" data-id="${p.id}">${detail}<div class="sheet-save-row"><span id="sheet-save-status" class="subtle">${isDm?'Alterações sincronizadas em tempo real.':'A ficha guarda-se automaticamente na mesa local.'}</span><button class="btn primary">Guardar agora</button></div></form></section>`;
  }
  function dmRender() {
    const campaign=state.campaign;
    const selectedMapPosition=state.map.tokens?.[mapSelectedToken]||{};
    const tabs=[['mesa','Mesa','✧'],['encontro','Encontro','⚔'],['mapa','Mapa','⌖'],['fichas','Personagens','♙'],['registo','Registo','◷']];
    const body = activeTab==='mesa'?`<div class="welcome"><section class="hero"><div class="eyebrow">${esc(campaign.chapter||'Capítulo I')} · ${['normal','night','battle','day'].includes(campaign.mode)?campaign.mode:'normal'}</div><h1>${esc(campaign.name)}</h1><p>O grimório da campanha está ligado. As alterações do DM, as fichas dos jogadores e as rolagens chegam aos ecrãs da mesa automaticamente.</p><div class="hero-actions"><button class="btn primary" data-tab="encontro">Preparar encontro</button><button class="btn" data-tab="mapa">Abrir mapa</button><button class="btn" data-action="next-turn">Próximo turno · R${campaign.round}</button></div></section><div class="quick-grid"><div class="quick"><strong>${state.players.filter(p=>p.character).length}<small> / 6</small></strong><span>aventureiros com ficha</span></div><div class="quick"><strong>${state.monsters.length+state.bosses.length}</strong><span>criaturas no encontro</span></div><div class="quick"><strong>R${campaign.round||1}</strong><span>ronda atual</span></div><div class="quick"><strong>${state.rolls.length}</strong><span>rolagens registadas</span></div></div></div><div class="layout"><div class="stack"><section class="panel"><div class="panel-head"><h2>Grupo de aventureiros</h2><button class="btn small" data-tab="fichas">Gerir fichas</button></div><div class="cards">${state.players.map(p=>actorCard(p,'player',true)).join('')}</div></section>${rollPanel()}</div><div class="stack"><section class="panel"><div class="panel-head"><h2>Registo da sessão</h2><button class="btn small" data-tab="registo">Ver tudo</button></div>${feed(state.log.slice(0,10))}</section><section class="panel"><div class="panel-head"><h2>Ambiente e música</h2></div>${modeButtons()}<div class="row" style="margin-top:11px"><label class="btn small" for="audio-file">Escolher música da batalha</label><input id="audio-file" class="file-hidden" type="file" accept="audio/*"><button class="btn small" data-action="music-test">▶ Testar</button><button class="btn small danger" data-action="music-remove">Remover</button></div><div class="subtle" style="margin-top:5px">${esc(state.battle.audioName||'Nenhuma música escolhida')}</div><div class="field" style="margin-top:8px"><label>VOLUME</label><input id="audio-volume" type="range" min="0" max="100" value="${Number(state.battle.volume)||70}"></div><div class="campaign-manager row"><select id="campaign-select" class="input">${(state.campaigns||[]).map(c=>'<option value="'+esc(c.id)+'" '+(c.id===state.campaignId?'selected':'')+'>'+esc(c.name)+'</option>').join('')}</select><button class="btn small" data-action="switch-campaign">Abrir</button><button class="btn small" data-action="create-campaign">Nova</button><button class="btn small danger" data-action="delete-campaign" ${state.campaigns.length<=1?'disabled':''}>Apagar</button></div><div class="form-grid" style="margin-top:13px"><div class="field"><label>CAMPANHA</label><input id="campaign-name" value="${esc(campaign.name)}"></div><div class="field"><label>CAPÍTULO</label><input id="campaign-chapter" value="${esc(campaign.chapter||'')}"></div></div><div class="row" style="margin-top:9px"><small id="campaign-save-status" class="subtle">A campanha sincroniza automaticamente.</small><button class="btn small primary" data-action="save-campaign">Guardar agora</button></div></section></div></div>`:
      activeTab==='encontro'?`<div class="layout"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Encontro ativo</h2><small>Ronda ${campaign.round} · turno ${campaign.activeTurn+1}${campaign.activeName?` · ${esc(campaign.activeName)}`:''}</small></div><div class="row"><button class="btn" data-action="roll-initiative">Rolar iniciativa</button><button class="btn primary" data-action="next-turn">Avançar turno</button></div></div><div class="cards">${state.players.map(p=>actorCard(p,'player',true)).join('')}${state.monsters.map(e=>actorCard(e,'monster',true)).join('')}${state.bosses.map(e=>actorCard(e,'boss',true)).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Adicionar criatura ao encontro</h2><small>Monstros e bosses separados</small></div><form id="entity-form" class="form-grid"><div class="field"><label>TIPO</label><select name="kind"><option value="monster">Monstro</option><option value="boss">Boss</option></select></div><div class="field"><label>NOME</label><input name="name" placeholder="Ex.: Dragão vermelho"></div><div class="field"><label>PONTOS DE VIDA</label><input name="hp" type="number" value="30" min="1"></div><div class="field"><label>CLASSE DE ARMADURA</label><input name="ac" type="number" value="15" min="1"></div><div class="field full"><button class="btn primary">Adicionar ao encontro</button><button class="btn" type="button" data-action="api-catalog" data-kind="monsters">Importar monstro / boss da API</button></div></form></section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>Tratamento rápido</h2></div>${targetSelect()}<div class="row" style="margin-top:9px"><input class="input grow" id="heal-amount" type="number" value="5" min="0" placeholder="PV"><button class="btn primary" data-action="heal-selected">Curar</button><button class="btn danger" data-action="damage-selected">Dano</button></div><div class="row" style="margin-top:8px"><input class="input grow" id="effect-name" placeholder="Ex.: Envenenado"><button class="btn" data-action="effect-selected">Aplicar efeito</button></div></section>${rollPanel()}</div></div>`:
      activeTab==='mapa'?`<div class="layout"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Mapa do encontro</h2><small>${esc(state.map.name||'Sem mapa carregado')}</small></div><button class="btn ${state.map.visible?'':'primary'}" data-action="toggle-map">${state.map.visible?'Ocultar do grupo':'Mostrar ao grupo'}</button></div>${mapHtml('dm')}</section><section class="panel"><div class="panel-head"><h2>Anotações no mapa</h2><button class="btn small" data-action="toggle-annotations">${state.map.annotationsVisible===false?'Mostrar anotações ao grupo':'Ocultar anotações do grupo'}</button></div><div class="row"><input id="map-note" class="input grow" maxlength="160" placeholder="Escreve uma nota curta"><input id="map-note-color" type="color" value="#e3bd63" class="input" style="max-width:60px;padding:4px"><button class="btn" data-action="toggle-note">${selectedToken==='__note__'?'Cancelar nota':'Colocar nota'}</button><button class="btn ${selectedToken==='__draw__'?'primary':''}" data-action="toggle-draw">${selectedToken==='__draw__'?'Terminar desenho':'Desenhar'}</button><button class="btn danger" data-action="clear-map-notes">Limpar desenhos e notas</button></div></section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>Preparar mapa</h2></div><label class="btn primary" for="map-file">Carregar imagem do mapa</label><input id="map-file" class="file-hidden" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><div class="field" style="margin-top:14px"><label>PEÇA A COLOCAR · CLICA NO MAPA</label><select id="token-select" class="input"><option value="">Escolhe personagem/criatura</option>${state.players.map(p=>`<option value="player:${p.id}" ${mapSelectedToken===`player:${p.id}`?'selected':''}>${esc(p.character||p.name)}${p.visible===false?' · oculta':''}</option>`).join('')}${state.monsters.map(m=>`<option value="monster:${esc(m.id)}" ${mapSelectedToken===`monster:${m.id}`?'selected':''}>${esc(m.name)}</option>`).join('')}${state.bosses.map(b=>`<option value="boss:${esc(b.id)}" ${mapSelectedToken===`boss:${b.id}`?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label>TAMANHO DA PEÇA NO MAPA · ${Number(selectedMapPosition.size)||42}px</label><input id="token-size" type="range" min="24" max="128" value="${Number(selectedMapPosition.size)||42}" ${mapSelectedToken?'':'disabled'}></div><label class="row subtle" style="margin-top:13px"><input id="grid-toggle" type="checkbox" ${state.map.grid?'checked':''}> Mostrar grelha</label><div class="field" style="margin-top:12px"><label>TAMANHO DA QUADRÍCULA</label><input id="grid-size" type="range" min="24" max="100" value="${Number(state.map.gridSize)||48}"></div><div class="empty-state" style="margin-top:13px">Seleciona uma peça e clica no mapa para a posicionar. Também podes arrastar uma peça já colocada.</div></section><section class="panel"><div class="panel-head"><h2>Ecrã público</h2></div><p class="subtle">O projetor mostra o mapa quando o DM o ativa e recebe rolagens públicas em tempo real.</p><a class="btn" href="/projector" target="_blank">Abrir vista do projetor ↗</a></section></div></div>`:
      activeTab==='fichas'?`<section class="panel"><div class="panel-head"><div><h2>Fichas dos jogadores</h2><small>A mesma ficha detalhada é partilhada entre a área do DM e o endereço de cada jogador.</small></div><div class="row">${state.players.map(p=>`<button class="btn small ${dmSheetPlayerId===p.id?'primary':''}" data-action="select-sheet-player" data-id="${p.id}">Player ${p.id}</button>`).join('')}</div></div><div class="subtle">Lugar: <b>${esc(state.players.find(p=>p.id===dmSheetPlayerId)?.name||`Player ${dmSheetPlayerId}`)}</b> · endereço /player/${dmSheetPlayerId}</div><div style="margin-top:14px">${renderSheet(state.players.find(p=>p.id===dmSheetPlayerId)||state.players[0],true)}</div></section>`:
      `<div class="layout"><section class="panel"><div class="panel-head"><h2>Diário da campanha</h2><button class="btn small" data-action="add-note">Adicionar anotação</button></div>${feed(state.log)}</section><div class="stack">${rollPanel()}<section class="panel"><div class="panel-head"><h2>Últimas rolagens</h2></div>${feed(state.rolls)}</section></div></div>`;
    root.innerHTML=`${header()}<main class="wrap">${navTabs(tabs,activeTab)}<div class="tab-pane">${body}</div><div class="footer">Made by: Carlos Arvela · Crónicas Web · dados guardados neste computador</div></main>`;
  }
  function modeButtons() { return `<div class="row">${[['day','☀ Dia'],['night','☾ Noite'],['battle','⚔ Batalha'],['normal','◌ Normal']].map(([v,t])=>`<button class="btn small ${state.campaign.mode===v?'primary':''}" data-action="mode" data-mode="${v}">${t}</button>`).join('')}</div>`; }
  function targetSelect() { const opts=[...state.players.map(p=>({id:p.id,kind:'player',name:p.character||p.name})),...state.monsters.map(p=>({id:p.id,kind:'monster',name:p.name})),...state.bosses.map(p=>({id:p.id,kind:'boss',name:p.name}))];return `<div class="field"><label>ALVO</label><select id="target-select" class="input">${opts.map(x=>`<option value="${x.kind}:${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></div>`; }
  function playerRender() {
    const p=activePlayer(),modes={normal:'◌ Normal',day:'☀ Dia',night:'☾ Noite',battle:'⚔ Batalha'},playerRolls=state.rolls.filter(x=>x.sourceKind==='player'),enemyRolls=state.rolls.filter(x=>['monster','boss'].includes(x.sourceKind));
    return `<main class="wrap ambient-${esc(state.campaign.mode)}"><div class="player-top"><div class="eyebrow">${esc(state.campaign.chapter||'Campanha')} · Player ${playerId}</div><h1>${esc(p.character||'A tua personagem')}</h1><p>${esc(state.campaign.name)} · ${modes[state.campaign.mode]||modes.normal}</p><div class="effects" style="justify-content:center;margin-top:13px">${(p.effects||[]).map(x=>`<span class="effect">${esc(x)}</span>`).join('')}</div></div>${state.battle.audioUrl?`<section class="panel music-panel"><div><div class="eyebrow">Música da mesa</div><b>${esc(state.battle.audioName||'Faixa da campanha')}</b><small>${state.campaign.mode==='battle'?'Música de batalha ativa':'A música toca quando o DM inicia batalha'}</small></div><button class="btn primary" data-action="music-toggle">${audioUnlocked&&!sharedAudio.paused?'Pausar música':'Ativar música'}</button></section>`:''}<div class="player-sheet"><section>${renderSheet(p,false)}</section><aside class="stack"><section class="panel"><div class="panel-head"><h2>Estado da campanha</h2></div><div class="quick-grid"><div class="quick"><strong>${esc(state.campaign.name)}</strong><span>campanha</span></div><div class="quick"><strong>${modes[state.campaign.mode]||modes.normal}</strong><span>ambiente definido pelo DM</span></div></div><div class="subtle" style="margin-top:12px">Capítulo: ${esc(state.campaign.chapter||'Capítulo I')} · Ronda ${Number(state.campaign.round)||1}</div></section>${state.players.length>1?`<section class="panel"><div class="panel-head"><h2>Grupo da campanha</h2></div><div class="cards">${state.players.map(x=>actorCard(x,'player')).join('')}</div></section>`:''}<section class="panel"><div class="panel-head"><h2>Dados dos jogadores</h2></div>${feed(playerRolls.slice(0,30))}</section><section class="panel"><div class="panel-head"><h2>Dados de monstros e bosses</h2></div>${feed(enemyRolls.slice(0,30))}</section>${state.monsters.length||state.bosses.length?`<section class="panel"><div class="panel-head"><h2>Criaturas reveladas</h2></div><div class="cards">${state.monsters.map(x=>actorCard(x,'monster')).join('')}${state.bosses.map(x=>actorCard(x,'boss')).join('')}</div></section>`:''}</aside></div>${state.map.visible?`<section class="panel" style="margin-top:16px"><div class="panel-head"><h2>Mapa da campanha</h2><small>${esc(state.map.name||'Mapa')}</small></div>${mapHtml('player')}</section>`:`<section class="panel"><div class="empty-state">O DM ainda não revelou o mapa desta cena.</div></section>`}<div class="footer">Made by: Carlos Arvela · Crónicas Web · Player ${playerId}</div></main>`;
  }
  function projectorRender() {
    const mapVisible=state.map.visible;
    return `<main class="projector"><div class="projector-head"><div><div class="eyebrow">${esc(state.campaign.chapter||'Capítulo I')} · Ronda ${state.campaign.round||1}</div><h1>${esc(state.campaign.name)}</h1>${state.battle.audioUrl?`<div class="row projector-audio"><button class="btn small primary" data-action="music-toggle">${audioUnlocked&&!sharedAudio.paused?'Pausar música':'Tocar música'}</button><small>${esc(state.battle.audioName||'Música da campanha')}</small></div>`:''}</div><div class="mode">${state.campaign.mode==='battle'?'⚔ Batalha':state.campaign.mode==='night'?'☾ Noite':state.campaign.mode==='day'?'☀ Dia':'◌ Normal'}</div></div><div class="projector-layout"><section class="panel">${mapVisible?mapHtml('projector'):`<div class="map-frame empty" style="height:calc(100vh - 180px)">O DM ainda não revelou o mapa desta cena.</div>`}</section><aside class="stack"><section class="panel"><div class="panel-head"><h2>Grupo</h2><small>estado partilhado</small></div><div class="projector-roster">${state.players.map(p=>`<div class="projector-player"><div class="avatar">${esc(initials(p.character||p.name))}</div><div><b>${esc(p.character||p.name)}</b><br><small>${(p.effects||[]).map(esc).join(' · ')||'Pronto para a aventura'}</small></div><b>${Number(p.hp)||0}/${Number(p.maxHp)||0} PV</b></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Rolagens públicas</h2></div>${feed(state.rolls.slice(0,12))}</section><section class="panel"><div class="panel-head"><h2>Diário público</h2></div>${feed(state.log.slice(0,12))}</section></aside></div><div class="footer">Crónicas · Made by: Carlos Arvela</div></main>`;
  }
  function render() {
    if(!state)return;
    if(role==='home'){ root.innerHTML=`<main class="launcher"><div class="brand"><div class="brand-mark">&</div><div><div class="brand-title">CRÓNICAS</div><div class="brand-sub">mesa de campanha local</div></div></div><div class="hero" style="margin-top:28px"><div class="eyebrow">Uma mesa · várias janelas</div><h1>Abre o teu lugar na campanha.</h1><p>Escolhe a vista para este ecrã. O servidor local mantém o grupo, o mapa e as rolagens sincronizados.</p><div class="launcher-grid"><a class="launch-card" href="/dm"><div class="launch-icon">♛</div><h2>Área do DM</h2><p>Controla encontro, fichas, mapa, ambiente e registo da sessão.</p></a>${Array.from({length:6},(_,i)=>`<a class="launch-card" href="/player/${i+1}"><div class="launch-icon">♙ ${i+1}</div><h2>Player ${i+1}</h2><p>Abre e atualiza a ficha deste lugar da mesa.</p></a>`).join('')}<a class="launch-card" href="/projector"><div class="launch-icon">▣</div><h2>Vista do projetor</h2><p>Mostra o mapa revelado, a ronda e as rolagens públicas.</p></a></div><div class="footer">Made by: Carlos Arvela · Os dados ficam no computador anfitrião</div></main>`; return; }
    if(role==='dm'){dmRender();}
    if(role==='player'){root.innerHTML=header()+playerRender();}
    if(role==='projector'){root.innerHTML=projectorRender();}
    bind();
  }
  function setPath(obj,path,value) { const bits=path.split('.');let target=obj;for(let i=0;i<bits.length-1;i++){const k=bits[i];target=target[k]??=(/^\d+$/.test(bits[i+1])?[]:{});}target[bits.at(-1)]=value; }
  function draftKey(el) { if(el.dataset.path)return `path:${el.dataset.path}`;if(el.dataset.listpath)return `list:${el.dataset.listpath}:${el.value}`;if(el.dataset.death)return `death:${el.dataset.death}`;return el.id?`id:${el.id}`:el.name?`name:${el.name}`:''; }
  function captureDraft() { const counts={},values=[];let focus=null;root.querySelectorAll('input,textarea,select').forEach(el=>{if(['file','button','submit'].includes(el.type))return;const key=draftKey(el);if(!key)return;const index=counts[key]||0;counts[key]=index+1;let selectionStart=null,selectionEnd=null;if(document.activeElement===el&&['text','search','url','tel','password','textarea'].includes(el.type||el.tagName.toLowerCase())){try{selectionStart=el.selectionStart;selectionEnd=el.selectionEnd;}catch{}}values.push({key,index,value:el.value,checked:el.checked,selectionStart,selectionEnd});if(document.activeElement===el)focus={key,index};});return{values,focus}; }
  function restoreDraft(draft) { if(!draft?.values?.length)return;const counts={},elements=[];root.querySelectorAll('input,textarea,select').forEach(el=>{if(['file','button','submit'].includes(el.type))return;const key=draftKey(el);if(!key)return;const index=counts[key]||0;counts[key]=index+1;elements.push({el,key,index});});for(const saved of draft.values){const found=elements.find(x=>x.key===saved.key&&x.index===saved.index)?.el;if(!found)continue;if(found.type==='checkbox'||found.type==='radio')found.checked=saved.checked;else found.value=saved.value;}if(draft.focus){const found=elements.find(x=>x.key===draft.focus.key&&x.index===draft.focus.index)?.el;if(found){found.focus({preventScroll:true});const saved=draft.values.find(x=>x.key===draft.focus.key&&x.index===draft.focus.index);try{if(saved.selectionStart!==null)found.setSelectionRange(saved.selectionStart,saved.selectionEnd);}catch{}}} }
  function queueSheetAutosave() { const status=$('#sheet-save-status');if(status)status.textContent='A guardar alterações…';clearTimeout(sheetSaveTimer);sheetSaveTimer=setTimeout(async()=>{sheetSaveTimer=null;if(sheetSaveBusy){sheetSaveQueued=true;return;}sheetSaveBusy=true;try{await saveSheetForm($('#sheet-form'),true);}catch{const label=$('#sheet-save-status');if(label)label.textContent='Falha ao guardar. Tenta novamente.';}finally{sheetSaveBusy=false;if(sheetSaveQueued){sheetSaveQueued=false;queueSheetAutosave();}}},650); }
  function queueCampaignAutosave() { clearTimeout(campaignSaveTimer);const status=$('#campaign-save-status');if(status)status.textContent='A guardar…';campaignSaveTimer=setTimeout(async()=>{campaignSaveTimer=null;try{await api('update-campaign',{patch:{name:$('#campaign-name')?.value||'',chapter:$('#campaign-chapter')?.value||''}});const label=$('#campaign-save-status');if(label)label.textContent='Campanha guardada automaticamente.';}catch{const label=$('#campaign-save-status');if(label)label.textContent='Falha ao guardar.';}},650); }
  async function flushCampaignFields() { clearTimeout(campaignSaveTimer);campaignSaveTimer=null;const name=$('#campaign-name')?.value,chapter=$('#campaign-chapter')?.value;if(name!==undefined&&(name!==state.campaign.name||chapter!==(state.campaign.chapter||'')))await api('update-campaign',{patch:{name,chapter}}); }
  async function saveSheetForm(form=$('#sheet-form'),quiet=false) {
    if(!form)return;const id=Number(form.dataset.id),p=state.players.find(x=>x.id===id);if(!p)return;const sheet=structuredClone(p.sheet);const status=$('#sheet-save-status');if(status)status.textContent='A sincronizar…';
    form.querySelectorAll('[data-path]').forEach(el=>{const value=el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''?'':Number(el.value)):el.value;setPath(sheet,el.dataset.path,value);});
    for(const group of ['saves','skills']){sheet[group]=[...form.querySelectorAll(`[data-listpath="${group}"]:checked`)].map(el=>el.value);}
    form.querySelectorAll('[data-death]').forEach(el=>{const [group,index]=el.dataset.death.split('.');sheet.deathSaves[group][Number(index)]=el.checked;});
    const cls=sheet.identity.className,level=Math.max(1,Math.min(20,Number(sheet.identity.level)||1)),hitDie=CLASS_INFO[cls]||10;
    sheet.identity.level=level;sheet.combat.proficiency=2+Math.floor((level-1)/4);if(cls)sheet.combat.hitDice=`${level}d${hitDie}`;
    if(sheet.hp.max!==''&&Number(sheet.hp.max)>0)sheet.hp.current=Math.max(0,Math.min(Number(sheet.hp.current)||0,Number(sheet.hp.max)));
    await api('update-player',{id,patch:{sheet}});if(status)status.textContent='Guardado automaticamente · sincronizado com a mesa.';if(!quiet)toast('Ficha guardada e sincronizada.');
  }
  function openDialog(title,label,initial,submit,type='text') {
    const overlay=document.createElement('div');overlay.className='dialog-backdrop';overlay.innerHTML=`<section class="dialog"><div class="panel-head"><h2>${esc(title)}</h2><button class="icon-btn" type="button" data-close>✕</button></div><form><div class="field"><label>${esc(label)}</label><input class="input" name="value" type="${type}" value="${esc(initial)}" ${type==='number'?'min="0"':''}></div><div class="row" style="justify-content:flex-end;margin-top:15px"><button class="btn" type="button" data-close>Cancelar</button><button class="btn primary">Confirmar</button></div></form></section>`;root.appendChild(overlay);const close=()=>overlay.remove();overlay.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);overlay.addEventListener('click',e=>{if(e.target===overlay)close();});overlay.querySelector('form').onsubmit=async e=>{e.preventDefault();const val=new FormData(e.currentTarget).get('value');await submit(val);close();};overlay.querySelector('input').focus();
  }
  function openCatalog(kind) {
    catalogKind=kind;const overlay=document.createElement('div');overlay.className='dialog-backdrop';overlay.innerHTML=`<section class="dialog catalog-dialog"><div class="panel-head"><div><h2>${kind==='spells'?'Catálogo de magias SRD':kind==='equipment'?'Armas e objetos SRD':'Monstros SRD 2014'}</h2><small>Lista e detalhes consultados pela API D&D 5e</small></div><button class="icon-btn" data-close>✕</button></div><form class="row"><input class="input grow" name="q" placeholder="Filtrar por nome"><button class="btn">Pesquisar</button></form><div class="catalog-status subtle" style="margin:9px 0">A carregar lista…</div><div class="catalog-results"></div></section>`;root.appendChild(overlay);overlay.querySelector('[data-close]').onclick=()=>overlay.remove();overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove();});
    const search=async q=>{const list=overlay.querySelector('.catalog-results'),status=overlay.querySelector('.catalog-status');status.textContent='A procurar na API…';try{const response=await fetch(`/api/catalog/${kind}?q=${encodeURIComponent(q||'')}`);const data=await response.json();if(!response.ok)throw new Error(data.error);status.textContent=`${data.count} resultados${data.count>250?' · a mostrar primeiros 250':''}`;list.innerHTML=data.results.map(item=>`<button class="catalog-item" type="button" data-url="${esc(item.url)}" data-name="${esc(item.name)}"><b>${esc(item.name)}</b><small>${esc(kind==='spells'?`Nível ${item.level} · ${item.school?.name||''}`:kind==='equipment'?item.equipment_category?.name||'Objeto':`${item.size||''} ${item.type||''} · ND ${item.challenge_rating??'—'}`)}</small></button>`).join('')||'<div class="empty-state">Sem resultados para este filtro.</div>';list.querySelectorAll('[data-url]').forEach(b=>b.onclick=async()=>{try{status.textContent='A carregar detalhes…';const res=await fetch(`/api/resource?url=${encodeURIComponent(b.dataset.url)}`);const detail=await res.json();if(!res.ok)throw new Error(detail.error);await importCatalogDetail(kind,detail);overlay.remove();}catch(err){status.textContent=err.message;}});}catch(err){status.textContent=`Não foi possível consultar a API: ${err.message}`;}};
    overlay.querySelector('form').onsubmit=e=>{e.preventDefault();search(new FormData(e.currentTarget).get('q'));};search('');
  }
  function apiText(value) { if(Array.isArray(value))return value.map(apiText).filter(Boolean).join('\n');if(value&&typeof value==='object')return value.name||value.desc||'';return String(value||''); }
  async function importCatalogDetail(kind,d) {
    if(kind==='monsters'){
      const hp=Number(d.hit_points)||1,ac=Number(d.armor_class?.[0]?.value)||10,first=(d.actions||[]).find(a=>a.attack_bonus!==undefined),damage=first?.damage?.[0]?.damage_dice||'d20';
      const dex=Number(d.dexterity)||10;const desc=[d.size,d.type,d.alignment,`Deslocamento: ${apiText(d.speed)}`,`Atributos: FOR ${d.strength} · DES ${d.dexterity} · CON ${d.constitution} · INT ${d.intelligence} · SAB ${d.wisdom} · CAR ${d.charisma}`,`Desafio: ${d.challenge_rating} · XP ${d.xp}`,...(d.special_abilities||[]).map(a=>`${a.name}: ${a.desc}`),...(d.actions||[]).map(a=>`${a.name}: ${a.desc}`)].filter(Boolean).join('\n');
      await api('add-entity',{kind:catalogTargetKind||'monster',entity:{name:d.name,hp,maxHp:hp,ac,type:d.type||'',size:d.size||'',initiative:Math.floor((dex-10)/2),attackBonus:Number(first?.attack_bonus)||0,die:damage,description:desc,attacks:d.actions||[]}});toast(`${d.name} importado da API.`);return;
    }
    const id=role==='dm'?dmSheetPlayerId:playerId,p=state.players.find(x=>x.id===id);if(!p)return;const sheet=structuredClone(p.sheet);
    if(kind==='spells'){const index=sheet.spells.findIndex(x=>!x.name);if(index<0){toast('As 17 linhas de magia estão preenchidas.');return;}const dc=d.dc||{},school=d.school?.name||'';sheet.spells[index]={prepared:false,name:d.name,source:'SRD 5.1',save:apiText(dc.dc_type)||apiText(d.attack_type),time:apiText(d.casting_time),range:apiText(d.range),components:apiText(d.components),duration:apiText(d.duration),level:String(d.level??0),notes:`${school}. ${apiText(d.desc)}`.trim()};}
    else {const index=sheet.inventory.findIndex(x=>!x.name);if(index<0){toast('As 12 linhas do inventário estão preenchidas.');return;}const damage=d.damage||{},properties=apiText(d.properties),category=apiText(d.equipment_category),description=apiText(d.desc);sheet.inventory[index]={name:d.name,quantity:'1',weight:d.weight??'',notes:[category,damage.damage_dice?`Dano ${damage.damage_dice} ${apiText(damage.damage_type)}`:'',properties,description].filter(Boolean).join(' · ')};if(String(d.equipment_category?.index||'').toLowerCase()==='weapon'){const attack=sheet.attacks.find(a=>!a.name);if(attack){attack.name=d.name;attack.damage=`${damage.damage_dice||''} ${apiText(damage.damage_type)}`.trim();attack.notes=properties;}}}
    await api('update-player',{id,patch:{sheet}});toast(kind==='spells'?'Magia importada da API.':'Objeto importado da API.');
  }
  function bind() {
    root.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{activeTab=b.dataset.tab;render();}));
    root.querySelectorAll('[data-sheet-tab]').forEach(b=>b.addEventListener('click',async()=>{sheetPage=b.dataset.sheetTab;await saveSheetForm();render();}));
    $('#sheet-form')?.addEventListener('input',queueSheetAutosave);
    $('#sheet-form')?.addEventListener('change',queueSheetAutosave);
    $('#sheet-form')?.addEventListener('submit',async e=>{e.preventDefault();clearTimeout(sheetSaveTimer);sheetSaveTimer=null;await saveSheetForm(e.currentTarget);});
    $('#sheet-form')?.querySelector('[data-path="identity.className"]')?.addEventListener('change',e=>{const die=CLASS_INFO[e.target.value];const sub=$('#sheet-form [data-path="identity.subclass"]');if(sub){const values=['',...(SUBCLASSES[e.target.value]||[])];sub.innerHTML=values.map(v=>`<option ${v===sub.value?'selected':''}>${esc(v)}</option>`).join('');if(!values.includes(sub.value))sub.value='';}if(die){const level=Math.max(1,Number($('#sheet-form [data-path="identity.level"]')?.value)||1);const hit=$('#sheet-form [data-path="combat.hitDice"]');if(hit)hit.value=`${level}d${die}`;const prof=$('#sheet-form [data-path="combat.proficiency"]');if(prof)prof.value=2+Math.floor((level-1)/4);}});
    $('#sheet-form')?.querySelector('[data-path="identity.level"]')?.addEventListener('change',e=>{const die=CLASS_INFO[$('#sheet-form [data-path="identity.className"]')?.value]||10;const hit=$('#sheet-form [data-path="combat.hitDice"]');if(hit)hit.value=`${Math.max(1,Number(e.target.value)||1)}d${die}`;const prof=$('#sheet-form [data-path="combat.proficiency"]');if(prof)prof.value=2+Math.floor((Math.max(1,Number(e.target.value)||1)-1)/4);});
    $('#roll-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('roll',{sides:Number(f.get('sides')),count:Number(f.get('count')),bonus:Number(f.get('bonus'))});});
    $('#entity-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('add-entity',{kind:f.get('kind'),entity:{name:f.get('name'),hp:Number(f.get('hp')),maxHp:Number(f.get('hp')),ac:Number(f.get('ac'))}});toast('Criatura adicionada ao encontro.');});
    $('#map-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});await api('map-upload',{name:file.name,dataUrl});toast('Mapa carregado.');});
    $('#audio-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});await api('media-upload',{name:file.name,dataUrl,volume:Number($('#audio-volume')?.value)||70});audioUnlocked=true;toast('Música carregada para a mesa.');});
    $('#portrait-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});await api('portrait-upload',{id:role==='dm'?dmSheetPlayerId:playerId,dataUrl});toast('Retrato guardado na ficha.');});
    $('#audio-volume')?.addEventListener('change',e=>api('battle-audio',{url:state.battle.audioUrl,name:state.battle.audioName,volume:Number(e.target.value)}));
    $('#grid-toggle')?.addEventListener('change',e=>api('map-options',{grid:e.target.checked,gridSize:Number($('#grid-size').value)}));$('#grid-size')?.addEventListener('change',e=>api('map-options',{grid:$('#grid-toggle').checked,gridSize:Number(e.target.value)}));
    $('#token-select')?.addEventListener('change',e=>{mapSelectedToken=e.target.value;const slider=$('#token-size');if(slider){slider.disabled=!mapSelectedToken;slider.value=state.map.tokens?.[mapSelectedToken]?.size||42;}const label=slider?.previousElementSibling;if(label&&slider)label.textContent=`TAMANHO DA PEÇA NO MAPA · ${slider.value}px`;});
    $('#token-size')?.addEventListener('change',e=>{if(mapSelectedToken)api('token-size',{key:mapSelectedToken,size:Number(e.target.value)});});
    $('#campaign-name')?.addEventListener('input',queueCampaignAutosave);$('#campaign-chapter')?.addEventListener('input',queueCampaignAutosave);
    $('#import-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{await api('import',{state:JSON.parse(await file.text())});toast('Campanha importada.');}catch(err){toast(err.message);}e.target.value='';});
    root.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',async()=>{
      const a=b.dataset.action;
      if(a==='mode')await api('set-mode',{mode:b.dataset.mode});
      if(a==='next-turn')await api('turn',{step:1});
      if(a==='toggle-map')await api('map-visible',{visible:!state.map.visible});
      if(a==='save-campaign'){await flushCampaignFields();}
      if(a==='switch-campaign'){await flushCampaignFields();const id=$('#campaign-select')?.value;if(id)await api('switch-campaign',{id});}
      if(a==='create-campaign'){await flushCampaignFields();openDialog('Nova campanha','Nome da campanha','Nova campanha',name=>api('create-campaign',{name}));}
      if(a==='delete-campaign'){await flushCampaignFields();const active=state.campaigns.find(c=>c.id===state.campaignId);openDialog('Apagar campanha','Escreve APAGAR para confirmar',`APAGAR`,value=>value==='APAGAR'?api('delete-campaign',{id:state.campaignId}):Promise.resolve());}
      if(a==='player-visibility'){const p=state.players.find(x=>x.id===Number(b.dataset.id));if(p)await api('toggle-player-visibility',{id:p.id,visible:p.visible===false});}
      if(a==='toggle-annotations')await api('annotations-visible',{visible:state.map.annotationsVisible===false});
      if(a==='heal-prompt'||a==='damage-prompt'){const method=a==='heal-prompt'?'heal':'damage';openDialog(method==='heal'?'Curar personagem ou criatura':'Aplicar dano','Pontos de vida',5,async amount=>api(method,{amount:Number(amount),target:{kind:b.dataset.kind,id:b.dataset.id,name:b.dataset.name}}),'number');}
      if(a==='effect-prompt')openDialog('Aplicar efeito ou condição',`Efeito em ${b.dataset.name}`,'',async effect=>{if(effect)await api('effect',{effect,target:{kind:b.dataset.kind,id:b.dataset.id,name:b.dataset.name}});});
      if(a==='delete-entity')openDialog('Remover criatura','Escreve REMOVER para confirmar',``,async value=>{if(value==='REMOVER')await api('delete-entity',{kind:b.dataset.kind,id:b.dataset.id});});
      if(a==='heal-selected'||a==='damage-selected'||a==='effect-selected'){const [kind,id]=$('#target-select').value.split(':');const opt=$('#target-select').selectedOptions[0];if(a==='heal-selected'||a==='damage-selected')await api(a==='heal-selected'?'heal':'damage',{amount:Number($('#heal-amount').value),target:{kind,id:kind==='player'?Number(id):id,name:opt.textContent}});else{const effect=$('#effect-name').value;if(effect)await api('effect',{effect,target:{kind,id:kind==='player'?Number(id):id,name:opt.textContent}});}}
      if(a==='toggle-note'){selectedToken=selectedToken==='__note__'?'__note__':'';render();}
      if(a==='toggle-draw'){selectedToken=selectedToken==='__draw__'?'':'__draw__';render();}
      if(a==='clear-map-notes')await api('clear-annotations');
      if(a==='add-note')openDialog('Diário da campanha','Anotação para a sessão','',async text=>{if(text)await api('log',{text});});
      if(a==='select-sheet-player'){dmSheetPlayerId=Number(b.dataset.id);sheetPage='combat';render();}
      if(a==='api-catalog'){await saveSheetForm();catalogTargetKind=$('#entity-form select[name="kind"]')?.value||'monster';openCatalog(b.dataset.kind);}
      if(a==='visibility-entity'){const kind=b.dataset.kind==='boss'?'boss':'monster',entity=[...state.monsters,...state.bosses].find(x=>x.id===b.dataset.id);if(entity)await api('update-entity',{kind,id:entity.id,patch:{visible:entity.visible===false}});}
      if(a==='roll-entity'){const kind=b.dataset.kind,entity=[...state.monsters,...state.bosses].find(x=>x.id===b.dataset.id);if(entity){const selected=b.closest('.actor')?.querySelector('[data-entity-die]')?.value||entity.die||'d20';const m=String(selected).match(/^(\d+)?d(\d+)(?:([+-])(\d+))?$/i);await api('roll',{sides:Number(m?.[2])||20,count:Number(m?.[1])||1,bonus:(Number(m?.[4])||0)*(m?.[3]==='-'?-1:1)+(Number(entity.attackBonus)||0),sourceKind:kind,sourceName:entity.name,entityId:entity.id});}}
      if(a==='roll-initiative')await api('roll-initiative');
      if(a==='music-toggle'){if(audioSource!==state.battle.audioUrl){audioSource=state.battle.audioUrl;sharedAudio.src=audioSource;sharedAudio.loop=true;}if(sharedAudio.paused){audioUnlocked=true;sharedAudio.volume=(Number(state.battle.volume)||70)/100;sharedAudio.play().catch(()=>toast('Clica novamente para permitir o áudio.'));}else{audioUnlocked=false;sharedAudio.pause();}render();}
      if(a==='music-test'){if(state.battle.audioUrl){audioUnlocked=true;sharedAudio.currentTime=0;sharedAudio.play().catch(()=>toast('Não foi possível tocar o áudio neste navegador.'));}}
      if(a==='music-remove')await api('battle-audio',{url:'',name:'',volume:state.battle.volume});
      if(a==='heal-sheet'||a==='damage-sheet'){const p=state.players.find(x=>x.id===Number(b.dataset.id));if(p)openDialog(a==='heal-sheet'?'Curar personagem':'Aplicar dano','Pontos de vida',5,amount=>api(a==='heal-sheet'?'heal':'damage',{amount:Number(amount),target:{kind:'player',id:p.id,name:p.character||p.name}}),'number');}
      if(a==='calculate-hp'){const form=$('#sheet-form');const level=Math.max(1,Number(form.querySelector('[data-path="identity.level"]')?.value)||1),die=CLASS_INFO[form.querySelector('[data-path="identity.className"]')?.value]||10,con=Math.floor(((Number(form.querySelector('[data-path="abilities.con"]')?.value)||10)-10)/2),max=Math.max(1,die+con)+(level-1)*Math.max(1,Math.floor(die/2)+1+con);form.querySelector('[data-path="hp.max"]').value=max;form.querySelector('[data-path="hp.current"]').value=max;}
      if(a==='export')exportCampaign();
    }));
    root.querySelectorAll('.map-frame[data-map]').forEach(map=>{
      const layer=map.querySelector('[data-draw-layer]');
      if(role==='dm'&&selectedToken==='__draw__'&&layer){let active=false,points=[],line=null;const coords=e=>{const r=layer.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};};layer.addEventListener('pointerdown',e=>{active=true;points=[coords(e)];line=document.createElementNS('http://www.w3.org/2000/svg','polyline');line.setAttribute('fill','none');line.setAttribute('stroke',$('#map-note-color')?.value||'#e3bd63');line.setAttribute('stroke-width','5');line.setAttribute('stroke-linecap','round');line.setAttribute('stroke-linejoin','round');line.setAttribute('vector-effect','non-scaling-stroke');layer.append(line);layer.setPointerCapture(e.pointerId);});layer.addEventListener('pointermove',e=>{if(!active)return;points.push(coords(e));line.setAttribute('points',points.map(p=>`${p.x*1000},${p.y*1000}`).join(' '));});layer.addEventListener('pointerup',async()=>{if(!active)return;active=false;if(points.length>1)await api('annotation',{points,color:$('#map-note-color')?.value||'#e3bd63'});});}
      map.addEventListener('click',async e=>{if(role!=='dm'||selectedToken==='__draw__'||e.target.closest('.map-token'))return;const rect=map.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width,y=(e.clientY-rect.top)/rect.height;if(selectedToken==='__note__'){const text=$('#map-note')?.value;if(text){selectedToken='';await api('annotation',{x,y,text,color:$('#map-note-color')?.value});}}else{const value=mapSelectedToken||$('#token-select')?.value;if(value){const [kind,id]=value.split(':');const ent=kind==='player'?state.players.find(p=>p.id===Number(id)):[...state.monsters,...state.bosses].find(p=>p.id===id);await api('place-token',{kind,id:kind==='player'?Number(id):id,x,y,size:Number($('#token-size')?.value)||42,name:ent?.character||ent?.name});}}});
      map.querySelectorAll('.map-token[data-token]').forEach(token=>{token.addEventListener('pointerdown',e=>{if(role!=='dm')return;e.preventDefault();token.setPointerCapture(e.pointerId);});token.addEventListener('pointerup',async e=>{if(role!=='dm')return;const rect=map.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width,y=(e.clientY-rect.top)/rect.height;const [kind,id]=token.dataset.token.split(':');await api('place-token',{kind,id:kind==='player'?Number(id):id,x,y,name:token.dataset.name});});});
    });
    root.querySelectorAll('[data-entity-die]').forEach(el=>el.addEventListener('change',()=>api('update-entity',{kind:el.dataset.kind,id:el.dataset.id,patch:{die:el.value}})));
    syncAudio();
  }
  function exportCampaign(){const data={characters:state.players.filter(p=>p.character).map(p=>{const s=p.sheet;const c={...s.identity,name:p.character,class:s.identity.className,race:s.identity.ancestry,level:s.identity.level,player_name:s.identity.playerName,xp:s.identity.xp,subclass:s.identity.subclass,background:s.identity.background,alignment:s.identity.alignment,abilities:{força:s.abilities.str,destreza:s.abilities.dex,constituição:s.abilities.con,inteligência:s.abilities.int,sabedoria:s.abilities.wis,carisma:s.abilities.cha},saves:s.saves,skills:s.skills,proficiency_bonus:s.combat.proficiency,initiative:String(s.combat.initiative),speed:s.combat.speed,inspiration:String(s.combat.inspiration),hit_dice:s.combat.hitDice,spellcasting_ability:s.spellcasting.ability||s.combat.spellcastingAbility,spell_save_dc:s.spellcasting.saveDc||s.combat.spellSaveDc,spell_attack_bonus:s.spellcasting.attackBonus||s.combat.spellAttackBonus,max_hp:s.hp.max,hp:s.hp.current,temp_hp:s.hp.temp,ac:s.ac,defenses:s.defenses,actions:s.actions,conditions:s.conditions,proficiencies:s.proficiencies,death_saves:s.deathSaves,features:s.features,background_details:s.history.story,personality_traits:s.history.personality,ideals:s.history.ideals,bonds:s.history.bonds,flaws:s.history.flaws,notes:s.history.notes,extras:s.history.extras,appearance:s.appearance.description,gender:s.appearance.gender,age:s.appearance.age,size:s.appearance.size,height:s.appearance.height,body_weight:s.appearance.weight,eyes:s.appearance.eyes,hair:s.appearance.hair,skin:s.appearance.skin,faith:s.appearance.faith,allies:s.appearance.allies,cp:s.currency.cp,sp:s.currency.sp,ep:s.currency.ep,gp:s.currency.gp,pp:s.currency.pp,weight_carried:s.carrying.weight,encumbered:s.carrying.encumbered,push_drag_lift:s.carrying.lift};for(let i=0;i<6;i++)for(const key of ['name','hit','damage','notes'])c[`attack_${key}_${i+1}`]=s.attacks[i]?.[key]||'';for(let i=0;i<12;i++)for(const key of ['name','quantity','weight','notes'])c[`equipment_${({quantity:'qty'})[key]||key}_${i+1}`]=s.inventory[i]?.[key]||'';for(let i=0;i<17;i++){const sp=s.spells[i]||{},n=i+1;for(const key of ['prepared','name','source','save','time','range','components','duration','level','notes'])c[`spell_${key==='level'?'page_ref':key}_${n}`]=key==='prepared'?(sp.prepared?'✓':''):(sp[key]||'');}return c;}),monsters:state.monsters.map(m=>({name:m.name,hp:m.hp,max_hp:m.maxHp,ac:m.ac,stats:m.description,attacks:m.attacks,attack_die:m.die,visible:m.visible})),bosses:state.bosses.map(m=>({name:m.name,hp:m.hp,max_hp:m.maxHp,ac:m.ac,stats:m.description,attacks:m.attacks,attack_die:m.die,revealed:m.visible})),map:state.map,log:state.log,roll_history:state.rolls};const blob=new Blob([JSON.stringify({format:'cronicas-campaign',version:1,campaign_name:state.campaign.name,exported_at:new Date().toISOString(),data},null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${(state.campaign.name||'campanha').replace(/[^\p{L}\p{N}-]+/gu,'-')}.json`;link.click();URL.revokeObjectURL(link.href);}
    load().then(()=>{const events=new EventSource(`/api/events?role=${role==='home'?'projector':role}&id=${playerId}`);events.addEventListener('state',e=>{const previousCampaign=state?.campaignId,draft=captureDraft();state=normalizeState(JSON.parse(e.data));render();if(previousCampaign===state.campaignId)restoreDraft(draft);});}).catch(e=>{root.innerHTML=`<main class="launcher"><h1>Não foi possível abrir a mesa.</h1><p>${esc(e?.message||String(e)||'Erro desconhecido ao carregar os dados.')}</p><p>Confirma que o servidor Node está em execução.</p><button class="btn primary" onclick="location.reload()">Tentar novamente</button></main>`;});
})();
